def blocuri(linii):
    """Corpul unui nod → blocuri: ('tabel', [linii]) | ('cod', [linii]) | ('text', [linii])."""
    out, cur, tip, fence = [], [], None, None
    def inchide():
        nonlocal cur, tip
        if cur:
            out.append((tip, cur))
        cur, tip = [], None
    for ln in linii:
        if fence:
            cur.append(ln)
            if ln.strip().startswith(fence):
                fence = None; inchide()
            continue
        m = re.match(r"\s*(```+|~~~+)", ln)
        if m:
            inchide(); tip, cur, fence = "cod", [ln], m.group(1)
            continue
        if _e_tabel(ln):
            if tip != "tabel":
                inchide(); tip = "tabel"
            cur.append(ln); continue
        if tip == "tabel":
            inchide()
        if not ln.strip():
            inchide(); continue
        if tip is None:
            tip = "text"
        cur.append(ln)
    inchide()
    return out


def arbore_md(text):
    """[(nivel, titlu, [linii corp])] — titlurile # … #### din afara blocurilor de cod; nivel 0 = textul dinaintea primului titlu."""
    sect, fence, cur = [(0, "", [])], None, None
    for ln in text.splitlines():
        m = re.match(r"\s*(```+|~~~+)", ln)
        if m:
            fence = None if fence and ln.strip().startswith(fence) else (fence or m.group(1))
        h = None if fence or m else re.match(r"(#{1,4})\s+(.*?)\s*#*\s*$", ln)
        if h:
            sect.append((len(h.group(1)), h.group(2), []))
        else:
